//! GPU kernel launcher for clause-parallel gradient SAT.
//!
//! Manages device memory and kernel dispatch for the Axis 1 loss kernel.
//! The PTX is compiled at build time by `warp-types-builder` and embedded
//! via `include!()`.
//!
//! # Usage
//!
//! ```ignore
//! let ctx = GpuContext::new()?;
//! let loss = ctx.total_loss(&soa, &x)?;
//! ```

use crate::gpu_gradient::ClauseDataSoA;
use cudarc::driver::*;
use std::sync::Arc;

// Generated by WarpBuilder in build.rs — contains KERNEL_PTX and Kernels struct.
mod sat_gpu_kernels {
    include!(concat!(env!("OUT_DIR"), "/kernels.rs"));
}

const WARP_SIZE: u32 = 32;
/// Per-slice flags of the device decode (must equal `sat-kernels::DEC_*`).
pub const DEC_CLEAN: u32 = 0;
pub const DEC_DIRTY: u32 = 1;
pub const DEC_NONE: u32 = 2;

/// GPU context holding CUDA device, stream, and loaded kernels.
///
/// Created once, reused across gradient iterations. Device buffers for
/// clause data are uploaded once (they don't change during optimization);
/// variable values are re-uploaded each iteration.
pub struct GpuContext {
    stream: Arc<CudaStream>,
    kernels: sat_gpu_kernels::Kernels,
}

/// Device-side SoA clause data. Uploaded once, reused across iterations.
pub struct GpuClauseData {
    vars0: CudaSlice<u32>,
    vars1: CudaSlice<u32>,
    vars2: CudaSlice<u32>,
    negs0: CudaSlice<u32>,
    negs1: CudaSlice<u32>,
    negs2: CudaSlice<u32>,
    weights: CudaSlice<f64>,
    /// Output buffer for per-batch partial sums.
    output: CudaSlice<f64>,
    num_clauses: u32,
    num_batches: u32,
    /// One past the highest variable index referenced by this clause data.
    ///
    /// The kernels index the caller's `x` (and gradient) buffers at
    /// `vars[i]` for every literal slot, INCLUDING padding clauses (their
    /// weight is 0, but the load still happens). Every entry point that
    /// accepts an `x` slice checks it against this bound: a short `x` is a
    /// device-side out-of-bounds access, which the launch `unsafe` block
    /// cannot detect and CUDA reports, at best, as a later async fault.
    num_vars: usize,
}

/// Errors from GPU operations.
#[derive(Debug)]
pub enum GpuError {
    Cuda(String),
}

impl std::fmt::Display for GpuError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            GpuError::Cuda(s) => write!(f, "CUDA error: {}", s),
        }
    }
}

impl std::error::Error for GpuError {}

impl From<cudarc::driver::DriverError> for GpuError {
    fn from(e: cudarc::driver::DriverError) -> Self {
        GpuError::Cuda(e.to_string())
    }
}

impl GpuContext {
    /// Initialize CUDA and load the SAT kernels.
    pub fn new() -> Result<Self, GpuError> {
        let ctx = CudaContext::new(0)?;
        let stream = ctx.default_stream();
        let kernels =
            sat_gpu_kernels::Kernels::load(&ctx).map_err(|e| GpuError::Cuda(e.to_string()))?;
        Ok(GpuContext { stream, kernels })
    }

    /// Upload SoA clause data to the GPU. Do this once per problem instance.
    pub fn upload_clause_data(&self, soa: &ClauseDataSoA) -> Result<GpuClauseData, GpuError> {
        let s = &self.stream;

        // Convert bool negation flags to u32 (0 or 1) for GPU
        let negs0_u32: Vec<u32> = soa.negs[0].iter().map(|&b| b as u32).collect();
        let negs1_u32: Vec<u32> = soa.negs[1].iter().map(|&b| b as u32).collect();
        let negs2_u32: Vec<u32> = soa.negs[2].iter().map(|&b| b as u32).collect();

        let num_batches = soa.num_batches() as u32;
        let num_vars = soa.num_vars();

        Ok(GpuClauseData {
            vars0: s.clone_htod(&soa.vars[0])?,
            vars1: s.clone_htod(&soa.vars[1])?,
            vars2: s.clone_htod(&soa.vars[2])?,
            negs0: s.clone_htod(&negs0_u32)?,
            negs1: s.clone_htod(&negs1_u32)?,
            negs2: s.clone_htod(&negs2_u32)?,
            weights: s.clone_htod(&soa.weights)?,
            output: s.clone_htod(&vec![0.0f64; num_batches as usize])?,
            num_clauses: soa.num_clauses as u32,
            num_batches,
            num_vars,
        })
    }

    /// Re-upload weights after clause weight update (EMA adaptation).
    pub fn update_weights(
        &self,
        gpu_data: &mut GpuClauseData,
        soa: &ClauseDataSoA,
    ) -> Result<(), GpuError> {
        gpu_data.weights = self.stream.clone_htod(&soa.weights)?;
        Ok(())
    }

    /// Compute total loss on GPU. Call each gradient iteration.
    ///
    /// Uploads variable values, launches kernel, downloads + sums partial results.
    /// The kernel result is identical to `total_loss_simwarp()` — same butterfly
    /// reduce, same operation order, same floating-point result.
    ///
    /// # Panics
    /// Panics if `x` is shorter than the clause data's variable count — the
    /// kernel would read `x[var]` out of bounds on the device.
    pub fn total_loss(&self, gpu_data: &GpuClauseData, x: &[f64]) -> Result<f64, GpuError> {
        assert!(
            x.len() >= gpu_data.num_vars,
            "total_loss: x has {} entries but the clause data references {} variables — \
             the kernel would index x out of bounds on the device",
            x.len(),
            gpu_data.num_vars
        );
        let s = &self.stream;

        // Upload current variable values (changes each iteration)
        let dev_x = s.clone_htod(x)?;

        // Launch: one block per warp-batch, 32 threads per block
        unsafe {
            s.launch_builder(&self.kernels.clause_loss_reduce)
                .arg(&gpu_data.vars0)
                .arg(&gpu_data.vars1)
                .arg(&gpu_data.vars2)
                .arg(&gpu_data.negs0)
                .arg(&gpu_data.negs1)
                .arg(&gpu_data.negs2)
                .arg(&gpu_data.weights)
                .arg(&dev_x)
                .arg(&gpu_data.output)
                .arg(&gpu_data.num_clauses)
                .launch(LaunchConfig {
                    grid_dim: (gpu_data.num_batches, 1, 1),
                    block_dim: (WARP_SIZE, 1, 1),
                    shared_mem_bytes: 0,
                })?;
        }

        // Download partial sums and accumulate on CPU
        let partial_sums = s.clone_dtoh(&gpu_data.output)?;
        Ok(partial_sums.iter().sum())
    }

    /// Fused loss + gradient on GPU. Single kernel launch.
    ///
    /// Returns `(total_loss, gradient_vec)`. The gradient is accumulated via
    /// f64 atomicAdd — non-deterministic reduction order means results match
    /// CPU to ~1e-10 but are not bit-identical.
    ///
    /// # Panics
    /// Panics if `x` or the `num_vars`-sized gradient buffer is smaller than
    /// the clause data's variable count. The kernel reads `x[var]` and
    /// atomically accumulates into `grad[var]` for every literal, so both
    /// buffers must cover every variable the clause data mentions.
    pub fn total_loss_and_grad(
        &self,
        gpu_data: &GpuClauseData,
        x: &[f64],
        num_vars: usize,
    ) -> Result<(f64, Vec<f64>), GpuError> {
        assert!(
            x.len() >= gpu_data.num_vars,
            "total_loss_and_grad: x has {} entries but the clause data references {} \
             variables — the kernel would index x out of bounds on the device",
            x.len(),
            gpu_data.num_vars
        );
        assert!(
            num_vars >= gpu_data.num_vars,
            "total_loss_and_grad: gradient buffer sized for {num_vars} variables but the \
             clause data references {} — the kernel's atomicAdd would write out of bounds \
             on the device",
            gpu_data.num_vars
        );
        let s = &self.stream;

        let dev_x = s.clone_htod(x)?;
        // Zero-initialized gradient accumulator
        let dev_grad = s.clone_htod(&vec![0.0f64; num_vars])?;

        unsafe {
            s.launch_builder(&self.kernels.clause_loss_grad_fused)
                .arg(&gpu_data.vars0)
                .arg(&gpu_data.vars1)
                .arg(&gpu_data.vars2)
                .arg(&gpu_data.negs0)
                .arg(&gpu_data.negs1)
                .arg(&gpu_data.negs2)
                .arg(&gpu_data.weights)
                .arg(&dev_x)
                .arg(&gpu_data.output)
                .arg(&dev_grad)
                .arg(&gpu_data.num_clauses)
                .launch(LaunchConfig {
                    grid_dim: (gpu_data.num_batches, 1, 1),
                    block_dim: (WARP_SIZE, 1, 1),
                    shared_mem_bytes: 0,
                })?;
        }

        let partial_sums = s.clone_dtoh(&gpu_data.output)?;
        let grad = s.clone_dtoh(&dev_grad)?;
        Ok((partial_sums.iter().sum(), grad))
    }

    /// GPU device name (for diagnostics).
    pub fn device_name(&self) -> String {
        "GPU".to_string()
    }

    // ── Device-resident iteration state ─────────────────────────────────

    /// Allocate device-resident buffers for the gradient iteration loop.
    ///
    /// Keeps x, grad, and velocity on device across iterations, eliminating
    /// the per-iteration host↔device transfer of grad (download) and x (upload).
    pub fn alloc_iter_state(&self, x: &[f64]) -> Result<GpuIterState, GpuError> {
        let s = &self.stream;
        let num_vars = x.len();
        let num_var_batches = ((num_vars + WARP_SIZE as usize - 1) / WARP_SIZE as usize) as u32;

        Ok(GpuIterState {
            dev_x: s.clone_htod(x)?,
            dev_grad: s.clone_htod(&vec![0.0f64; num_vars])?,
            dev_velocity: s.clone_htod(&vec![0.0f64; num_vars])?,
            grad_norm_output: s.clone_htod(&vec![0.0f64; num_var_batches as usize])?,
            dev_lr: s.clone_htod(&[0.0f64])?,
            dev_momentum: s.clone_htod(&[0.0f64])?,
            num_vars: num_vars as u32,
            num_var_batches,
        })
    }

    /// Run one gradient iteration on GPU: fused loss+grad → variable update → grad norm.
    ///
    /// Returns (total_loss, grad_norm_sq). All intermediate data stays on device.
    /// The only downloads are: loss partial sums (num_batches × 8 bytes) and
    /// grad norm partial sums (num_var_batches × 8 bytes).
    pub fn gpu_iteration(
        &self,
        gpu_data: &GpuClauseData,
        state: &mut GpuIterState,
        lr: f64,
        momentum: f64,
    ) -> Result<(f64, f64), GpuError> {
        assert!(
            state.num_vars as usize >= gpu_data.num_vars,
            "gpu_iteration: iteration state covers {} variables but the clause data \
             references {} — the kernels would index dev_x/dev_grad out of bounds \
             on the device",
            state.num_vars,
            gpu_data.num_vars
        );
        let s = &self.stream;

        // Zero grad accumulator for this iteration
        let zeros = vec![0.0f64; state.num_vars as usize];
        state.dev_grad = s.clone_htod(&zeros)?;

        // Upload scalar parameters
        state.dev_lr = s.clone_htod(&[lr])?;
        state.dev_momentum = s.clone_htod(&[momentum])?;

        // ── Kernel 1: fused loss + gradient ──
        unsafe {
            s.launch_builder(&self.kernels.clause_loss_grad_fused)
                .arg(&gpu_data.vars0)
                .arg(&gpu_data.vars1)
                .arg(&gpu_data.vars2)
                .arg(&gpu_data.negs0)
                .arg(&gpu_data.negs1)
                .arg(&gpu_data.negs2)
                .arg(&gpu_data.weights)
                .arg(&state.dev_x)
                .arg(&gpu_data.output)
                .arg(&state.dev_grad)
                .arg(&gpu_data.num_clauses)
                .launch(LaunchConfig {
                    grid_dim: (gpu_data.num_batches, 1, 1),
                    block_dim: (WARP_SIZE, 1, 1),
                    shared_mem_bytes: 0,
                })?;
        }

        // ── Kernel 2: variable update (reads grad, updates x + velocity) ──
        unsafe {
            s.launch_builder(&self.kernels.variable_update)
                .arg(&state.dev_x)
                .arg(&state.dev_grad)
                .arg(&state.dev_velocity)
                .arg(&state.dev_lr)
                .arg(&state.dev_momentum)
                .arg(&state.num_vars)
                .launch(LaunchConfig {
                    grid_dim: (state.num_var_batches, 1, 1),
                    block_dim: (WARP_SIZE, 1, 1),
                    shared_mem_bytes: 0,
                })?;
        }

        // ── Kernel 3: gradient norm reduction (reads grad, reduces grad²) ──
        unsafe {
            s.launch_builder(&self.kernels.grad_norm_reduce)
                .arg(&state.dev_grad)
                .arg(&state.grad_norm_output)
                .arg(&state.num_vars)
                .launch(LaunchConfig {
                    grid_dim: (state.num_var_batches, 1, 1),
                    block_dim: (WARP_SIZE, 1, 1),
                    shared_mem_bytes: 0,
                })?;
        }

        // Download only the small aggregation buffers
        let loss_partials = s.clone_dtoh(&gpu_data.output)?;
        let norm_partials = s.clone_dtoh(&state.grad_norm_output)?;

        let total_loss: f64 = loss_partials.iter().sum();
        let grad_norm_sq: f64 = norm_partials.iter().sum();

        Ok((total_loss, grad_norm_sq))
    }

    /// Download current x values from device for verification.
    pub fn download_x(&self, state: &GpuIterState) -> Result<Vec<f64>, GpuError> {
        Ok(self.stream.clone_dtoh(&state.dev_x)?)
    }

    /// Re-upload x values to device (e.g., after host-side random init for a new start).
    ///
    /// # Panics
    /// Panics if `x` does not have exactly `state.num_vars` entries. The
    /// device buffers are replaced with ones sized from `x`, but the kernels
    /// are still launched over `state.num_vars` — a short `x` would leave
    /// `variable_update` writing past the end of `dev_x` on the device.
    pub fn upload_x(&self, state: &mut GpuIterState, x: &[f64]) -> Result<(), GpuError> {
        assert_eq!(
            x.len(),
            state.num_vars as usize,
            "upload_x: x has {} entries but the iteration state is launched over {} \
             variables",
            x.len(),
            state.num_vars
        );
        state.dev_x = self.stream.clone_htod(x)?;
        state.dev_velocity = self.stream.clone_htod(&vec![0.0f64; x.len()])?;
        Ok(())
    }
}

/// Device-resident state for the gradient iteration loop.
///
/// Holds x, grad, and velocity on GPU across iterations. Created once per
/// solve attempt, re-uploaded per start (random init).
pub struct GpuIterState {
    dev_x: CudaSlice<f64>,
    dev_grad: CudaSlice<f64>,
    dev_velocity: CudaSlice<f64>,
    grad_norm_output: CudaSlice<f64>,
    dev_lr: CudaSlice<f64>,
    dev_momentum: CudaSlice<f64>,
    num_vars: u32,
    num_var_batches: u32,
}

// ─── LRAT lemma checking on the device ────────────────────────────────

impl GpuContext {
    /// Check every lemma of a flat LRAT proof on the device with
    /// `sat-kernels::lrat_check_lemmas`; returns one code per lemma (the
    /// `lrat_warp::LemmaCode` numbering). `blocks` warps run grid-stride
    /// over the lemmas; each gets a `LRAT_TABLE`-slot scratch table.
    ///
    /// Everything about the verdict (earliest failing lemma, the empty
    /// clause) is decided on the host from the codes, as for the SimWarp
    /// path — this method is the device half only.
    pub fn check_lrat_codes(
        &self,
        fp: &crate::lrat_warp::FlatProof,
        blocks: u32,
    ) -> Result<Vec<u8>, GpuError> {
        const TABLE: u32 = 4096; // must equal sat-kernels::LRAT_TABLE
        let s = &self.stream;
        let n = fp.lemma_clause.len() as u32;
        if n == 0 {
            return Ok(Vec::new());
        }
        let blocks = blocks.max(1).min(n);
        let lits = s.clone_htod(&fp.lits)?;
        let clause_start = s.clone_htod(&fp.clause_start)?;
        let deleted_at = s.clone_htod(&fp.deleted_at)?;
        let lemma_clause = s.clone_htod(&fp.lemma_clause)?;
        let lemma_step = s.clone_htod(&fp.lemma_step)?;
        let hint_start = s.clone_htod(&fp.hint_start)?;
        let hints = s.clone_htod(&fp.hints)?;
        let table_keys: CudaSlice<u32> = s.alloc_zeros((blocks * TABLE) as usize)?;
        let table_stamps: CudaSlice<u32> = s.alloc_zeros((blocks * TABLE) as usize)?;
        // Pre-filled with `LemmaCode::Unwritten` (6): a lemma the kernel never
        // wrote must fail, not read as Ok (= 0). Cross-vendor panel 2026-11-02.
        let codes: CudaSlice<u8> = s.clone_htod(&vec![6u8; n as usize])?;
        unsafe {
            s.launch_builder(&self.kernels.lrat_check_lemmas)
                .arg(&lits)
                .arg(&clause_start)
                .arg(&deleted_at)
                .arg(&lemma_clause)
                .arg(&lemma_step)
                .arg(&hint_start)
                .arg(&hints)
                .arg(&table_keys)
                .arg(&table_stamps)
                .arg(&codes)
                .arg(&n)
                .arg(&blocks)
                .launch(LaunchConfig {
                    grid_dim: (blocks, 1, 1),
                    block_dim: (WARP_SIZE, 1, 1),
                    shared_mem_bytes: 0,
                })?;
        }
        Ok(s.clone_dtoh(&codes)?)
    }
    /// Phase 1 of the binary LRAT decode on the device
    /// (`sat-kernels::lrat_scan_slices`, or the thread-per-slice control when
    /// `cooperative` is false): upload the bytes, count per slice, prefix the
    /// counts on the host, write the records, download everything. The
    /// result is phase-1 records in slice order; `lrat_warp` turns them into
    /// `RawChunk`s and stitches them exactly as the host workers' records.
    pub fn decode_lrat_slices(
        &self,
        bytes: &[u8],
        slice: u32,
        cooperative: bool,
        blocks: u32,
    ) -> Result<DeviceSlices, GpuError> {
        use std::time::Instant;
        let s = &self.stream;
        let len = bytes.len() as u64;
        let slice = slice.max(1);
        let n_slices = (bytes.len() as u64).div_ceil(slice as u64) as u32;
        if n_slices == 0 {
            return Ok(DeviceSlices::default());
        }
        let t0 = Instant::now();
        let d_bytes = s.clone_htod(bytes)?;
        s.synchronize()?;
        let t_upload = t0.elapsed();
        let s_start: CudaSlice<u64> = s.alloc_zeros(n_slices as usize)?;
        let s_end: CudaSlice<u64> = s.alloc_zeros(n_slices as usize)?;
        let s_flags: CudaSlice<u32> = s.alloc_zeros(n_slices as usize)?;
        let mut s_cnt: CudaSlice<u32> = s.alloc_zeros(4 * n_slices as usize)?;
        // Pass 1 needs the record pointers to exist; one element each.
        let mut st_pos: CudaSlice<u64> = s.alloc_zeros(1)?;
        let mut st_id: CudaSlice<u64> = s.alloc_zeros(1)?;
        let mut st_after: CudaSlice<u64> = s.alloc_zeros(1)?;
        let mut st_lit_end: CudaSlice<u32> = s.alloc_zeros(1)?;
        let mut st_hint_end: CudaSlice<u32> = s.alloc_zeros(1)?;
        let mut st_del_end: CudaSlice<u32> = s.alloc_zeros(1)?;
        let mut st_tag: CudaSlice<u8> = s.alloc_zeros(1)?;
        let mut st_rat: CudaSlice<u8> = s.alloc_zeros(1)?;
        let mut o_lits: CudaSlice<i32> = s.alloc_zeros(1)?;
        let mut o_hints: CudaSlice<u64> = s.alloc_zeros(1)?;
        let mut o_del_id: CudaSlice<u64> = s.alloc_zeros(1)?;
        let mut o_del_pos: CudaSlice<u64> = s.alloc_zeros(1)?;
        let (grid, num_blocks) = if cooperative {
            let b = blocks.max(1).min(n_slices);
            (b, b)
        } else {
            (n_slices.div_ceil(WARP_SIZE), 0)
        };
        let launch = |pass: u32,
                      s_cnt: &CudaSlice<u32>,
                      st_pos: &CudaSlice<u64>,
                      st_id: &CudaSlice<u64>,
                      st_after: &CudaSlice<u64>,
                      st_lit_end: &CudaSlice<u32>,
                      st_hint_end: &CudaSlice<u32>,
                      st_del_end: &CudaSlice<u32>,
                      st_tag: &CudaSlice<u8>,
                      st_rat: &CudaSlice<u8>,
                      o_lits: &CudaSlice<i32>,
                      o_hints: &CudaSlice<u64>,
                      o_del_id: &CudaSlice<u64>,
                      o_del_pos: &CudaSlice<u64>|
         -> Result<(), GpuError> {
            let f = if cooperative {
                &self.kernels.lrat_scan_slices
            } else {
                &self.kernels.lrat_scan_slices_serial
            };
            unsafe {
                s.launch_builder(f)
                    .arg(&d_bytes)
                    .arg(&len)
                    .arg(&slice)
                    .arg(&n_slices)
                    .arg(&num_blocks)
                    .arg(&pass)
                    .arg(&s_start)
                    .arg(&s_end)
                    .arg(&s_flags)
                    .arg(s_cnt)
                    .arg(st_pos)
                    .arg(st_id)
                    .arg(st_after)
                    .arg(st_lit_end)
                    .arg(st_hint_end)
                    .arg(st_del_end)
                    .arg(st_tag)
                    .arg(st_rat)
                    .arg(o_lits)
                    .arg(o_hints)
                    .arg(o_del_id)
                    .arg(o_del_pos)
                    .launch(LaunchConfig {
                        grid_dim: (grid, 1, 1),
                        block_dim: (WARP_SIZE, 1, 1),
                        shared_mem_bytes: 0,
                    })?;
            }
            Ok(())
        };
        let t1 = Instant::now();
        launch(
            1,
            &s_cnt,
            &st_pos,
            &st_id,
            &st_after,
            &st_lit_end,
            &st_hint_end,
            &st_del_end,
            &st_tag,
            &st_rat,
            &o_lits,
            &o_hints,
            &o_del_id,
            &o_del_pos,
        )?;
        s.synchronize()?;
        let t_pass1 = t1.elapsed();
        // ---- host prefix over the per-slice counts ----
        let t2 = Instant::now();
        let counts: Vec<u32> = s.clone_dtoh(&s_cnt)?;
        let flags: Vec<u32> = s.clone_dtoh(&s_flags)?;
        let mut offs = vec![0u32; counts.len()];
        let mut tot = [0u32; 4];
        for i in 0..n_slices as usize {
            for f in 0..4 {
                offs[4 * i + f] = tot[f];
                tot[f] = tot[f]
                    .checked_add(counts[4 * i + f])
                    .ok_or_else(|| GpuError::Cuda("decode: more than 2^32 records".into()))?;
            }
        }
        s_cnt = s.clone_htod(&offs)?;
        let t_prefix = t2.elapsed();
        // ---- pass 2 into exactly-sized arrays ----
        let n_steps = tot[0].max(1) as usize;
        let n_lits = tot[1].max(1) as usize;
        let n_hints = tot[2].max(1) as usize;
        let n_dels = tot[3].max(1) as usize;
        st_pos = s.alloc_zeros(n_steps)?;
        st_id = s.alloc_zeros(n_steps)?;
        st_after = s.alloc_zeros(n_steps)?;
        st_lit_end = s.alloc_zeros(n_steps)?;
        st_hint_end = s.alloc_zeros(n_steps)?;
        st_del_end = s.alloc_zeros(n_steps)?;
        st_tag = s.alloc_zeros(n_steps)?;
        st_rat = s.alloc_zeros(n_steps)?;
        o_lits = s.alloc_zeros(n_lits)?;
        o_hints = s.alloc_zeros(n_hints)?;
        o_del_id = s.alloc_zeros(n_dels)?;
        o_del_pos = s.alloc_zeros(n_dels)?;
        let t3 = Instant::now();
        launch(
            2,
            &s_cnt,
            &st_pos,
            &st_id,
            &st_after,
            &st_lit_end,
            &st_hint_end,
            &st_del_end,
            &st_tag,
            &st_rat,
            &o_lits,
            &o_hints,
            &o_del_id,
            &o_del_pos,
        )?;
        s.synchronize()?;
        let t_pass2 = t3.elapsed();
        let t4 = Instant::now();
        let out = DeviceSlices {
            slice: slice as usize,
            n_slices: n_slices as usize,
            starts: s.clone_dtoh(&s_start)?,
            ends: s.clone_dtoh(&s_end)?,
            flags,
            offs,
            totals: tot,
            st_pos: s.clone_dtoh(&st_pos)?,
            st_id: s.clone_dtoh(&st_id)?,
            st_after: s.clone_dtoh(&st_after)?,
            st_lit_end: s.clone_dtoh(&st_lit_end)?,
            st_hint_end: s.clone_dtoh(&st_hint_end)?,
            st_del_end: s.clone_dtoh(&st_del_end)?,
            st_tag: s.clone_dtoh(&st_tag)?,
            st_rat: s.clone_dtoh(&st_rat)?,
            lits: s.clone_dtoh(&o_lits)?,
            hints: s.clone_dtoh(&o_hints)?,
            del_id: s.clone_dtoh(&o_del_id)?,
            del_pos: s.clone_dtoh(&o_del_pos)?,
            timing: DecodeTiming {
                upload: t_upload,
                pass1: t_pass1,
                prefix: t_prefix,
                pass2: t_pass2,
                download: t4.elapsed(),
            },
        };
        Ok(out)
    }
}

/// Stage times of [`GpuContext::decode_lrat_slices`].
#[derive(Debug, Clone, Copy, Default)]
pub struct DecodeTiming {
    pub upload: std::time::Duration,
    pub pass1: std::time::Duration,
    pub prefix: std::time::Duration,
    pub pass2: std::time::Duration,
    pub download: std::time::Duration,
}

/// Phase-1 records from the device, slice-major: slice `i` owns steps
/// `offs[4i]..offs[4i] + count`, and so on for lits / hints / dels (the
/// counts are the differences between consecutive offsets, the last one
/// against `totals`). Step fields `*_end` are slice-local, as in the host
/// workers' records. `flags[i]`: 0 clean, 1 dirty (re-parse on the host),
/// 2 no candidate start.
#[derive(Debug, Clone, Default)]
pub struct DeviceSlices {
    pub slice: usize,
    pub n_slices: usize,
    pub starts: Vec<u64>,
    pub ends: Vec<u64>,
    pub flags: Vec<u32>,
    pub offs: Vec<u32>,
    pub totals: [u32; 4],
    pub st_pos: Vec<u64>,
    pub st_id: Vec<u64>,
    pub st_after: Vec<u64>,
    pub st_lit_end: Vec<u32>,
    pub st_hint_end: Vec<u32>,
    pub st_del_end: Vec<u32>,
    pub st_tag: Vec<u8>,
    pub st_rat: Vec<u8>,
    pub lits: Vec<i32>,
    pub hints: Vec<u64>,
    pub del_id: Vec<u64>,
    pub del_pos: Vec<u64>,
    pub timing: DecodeTiming,
}
